import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`dental-audit`,heroTitle:`Book more patients in minutes`,heroSubtitle:`Perplexity Computer audits your website, reviews, and booking flow, then delivers a plan to fill your schedule — automatically.`,inputUrlCta:`Audit my practice`,inputUrlPlaceholder:`yourdentist.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this dental practice. (1) Audit the website for mobile experience, appointment booking flow, service pages, insurance info, and local SEO. (2) Review the Google Business Profile for completeness, photos, and response rate to reviews. (3) Analyze Google reviews and Healthgrades profile for recurring patient complaints about wait times, billing, and bedside manner. (4) Benchmark against the top 5 dental practices in the same area for review volume, services offered, and online booking experience. (5) Deliver an actionable plan to book more patients, improve ratings, and reduce no-shows — with specific fixes prioritized by patient acquisition impact.`,heroOverlaySteps:[`Auditing your website for booking flow, service pages, and insurance info`,`Analyzing Google reviews and Healthgrades for patient complaints and praise`,`Benchmarking against the top 5 dental practices in your area`,`Patient growth plan with booking fixes, review templates, and SEO improvements — ready to execute`],generatingSteps:[`Visiting {url} to audit your website, booking flow, and service pages`,`Designing an agent to analyze patient reviews and local search rankings`,`Configuring competitor benchmarking and patient sentiment pipelines`,`Setting up growth plan report with booking optimization and retention tactics`],featureSectionTitle:`From checkup to chair time`,featureCardTitles:[`Connects to your practice stack`,`Fixes that fill your schedule`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Analytics, Gmail, Notion — Computer plugs into your tools so audits, reminders, and patient follow-ups happen in one workflow.`,`Booking flow improvements. Review response templates. Local SEO fixes. No-show reduction tactics. Computer delivers changes ranked by patient acquisition impact.`],capabilitySectionTitle:`Your patient acquisition team, on autopilot`,capabilitySectionSubtitle:`Paste your practice URL, get back a complete patient growth plan.`,capabilityCards:[{title:`Booking Flow Audit`,description:`Computer can audit your entire patient booking path — from landing page to confirmation — and flag every friction point costing you appointments.`},{title:`Patient Review Analysis`,description:`Computer can analyze Google reviews and Healthgrades profiles to surface wait-time complaints, billing issues, and staff praise — with trends over time.`},{title:`Local Practice Rankings`,description:`Computer can compare your ratings, review volume, services, and online booking experience against the top 5 practices in your area.`},{title:`Connect Your Tools`,description:`Computer can read from Google Sheets, Google Analytics, Gmail, and Notion — build workflows across your practice operations.`},{title:`Knows Your Practice`,description:`Computer can remember your services, insurance partners, and patient feedback patterns across sessions — so every audit builds on what came before.`},{title:`Review & Rating Alerts`,description:`Computer can watch your Google and Healthgrades reviews daily — and alert you when a patient review needs a response or your star rating dips.`}]});export{t as default};
